mapper.update:
UPDATE spot s JOIN (
SELECT #{spot.spotId} AS id, #{spot.columns.name} AS name, #{spot.columns.address} AS address, #{spot.columns.latitude} AS latitude, #{spot.columns.longitude} AS longitude, #{spot.columns.weatherNx} AS weather_nx, #{spot.columns.weatherNy} AS weather_ny
) AS changed ON changed.id = s.id SET s.name = changed.name, s.address = changed.address, s.location = ST_SRID(POINT(changed.longitude, changed.latitude), 4326), s.weather_nx = changed.weather_nx, s.weather_ny = changed.weather_ny, s.updated_at = #{now}

UPDATE public_spot_detail d JOIN (
SELECT #{spot.spotId} AS spot_id, #{spot.columns.category} AS category, #{spot.columns.facilities} AS facilities, #{spot.columns.phone} AS phone, #{spot.columns.homepage} AS homepage, #{spot.columns.operatingStatus} AS operating_status, #{spot.columns.closedFrom} AS closed_from, #{spot.columns.closedUntil} AS closed_until
) AS changed ON changed.spot_id = d.spot_id SET d.category = changed.category, d.facilities = CAST(changed.facilities AS JSON), d.phone = changed.phone, d.homepage = changed.homepage, d.operating_status = changed.operating_status, d.closed_from = CAST(changed.closed_from AS DATE), d.closed_until = CAST(changed.closed_until AS DATE), d.synced_at = #{now}, d.updated_at = #{now}

UPDATE public_spot_detail
SET source_removed_at = NULL,
    updated_at = #{now}
WHERE source_removed_at IS NOT NULL
